#if UNITY_EDITOR
using System.Collections.Generic;
using UnityEditor;
using UnityEngine;
using VfxKit;
using static VfxKit.VfxBuildKit;

namespace VfxEffects
{
    // Generated by vfx-shader. The prefab is rebuilt from this script: edit here, not in the Inspector.
    // Lightning strike from the sky onto one ground point (art lead 2026-11-04), built the way rpg-game's VFX_BossRaid_Knight_Thunder is
    // (rendered and compared, see vfx-shader references/lightning.md):
    //   * ground cracks: radial crack texture (T_VFX_Ground_Crack) flat on the ground, yellow, fades in then out over ~1.4 s
    //   * the strike: a Stretched Billboard whose sheet (lightning_texture_sheet1, 5 frames) breaks up a bolt over 0.15 s, fired twice;
    //     a main bolt and two thinner branch bolts that strike a little later next to it
    //   * white jagged arcs (HandPaintedLightning2, 3x3 sheet) thrown out of the strike point in every direction
    //   * impact (auto-mix flash + glow + ring + sparks, Docs/VFX/_Recipes/LightningStrike_Impact.json), scorch mark and ground glow
    public static class LightningStrikeBuild
    {
        const string Root = "Assets/VFX/LightningStrike";
        const string Lib = "Assets/VFX/_Imported/RpgGame/Lightning/Textures/";
        const string Recipe = "Docs/VFX/_Recipes/LightningStrike_Impact.json";
        const float Life = 2.4f;

        [MenuItem("VFX/LightningStrike/Build")]
        public static void Build()
        {
            if (!ConfirmSceneSwitch()) return;
            EnsureFolders(Root, "Materials", "Textures", "Prefabs", "Scenes");
            BuildAll();
        }

        public static void BuildBatch() => RunBatch(Build);

        static void BuildAll()
        {
            string M(string part) => Root + "/Materials/M_LightningStrike_" + part + ".mat";
            var mix = MixRecipeBuild.Build(Recipe);   // first: it opens its own scene

            // ---- textures (these already have an alpha channel)
            var crackTex = ImportTexture(Lib + "T_VFX_Ground_Crack.png", 512);
            var boltTex = ImportTexture(Lib + "lightning_texture_sheet1.png", 1024);
            var arcTex = ImportTexture(Lib + "HandPaintedLightning2.png", 512);
            var glowTex = ImportTexture(Root + "/Textures/T_LightningStrike_Glow.png", 256, alphaFromGray: true);

            var mCrack = Material(M("GroundCrack"), VfxBlend.Additive, crackTex);
            var mBolt = Material(M("Bolt"), VfxBlend.Additive, boltTex);
            var mArcs = Material(M("Arcs"), VfxBlend.Additive, arcTex);
            var mScorch = Material(M("Scorch"), VfxBlend.Alpha, glowTex);
            var mGlow = Material(M("GroundGlow"), VfxBlend.Additive, glowTex);

            // materials are re-used between builds: always reset tiling/offset (the 5x1 / 3x3 sheets are cut by Texture Sheet Animation only)
            foreach (var m in new[] { mCrack, mBolt, mArcs, mScorch, mGlow })
            {
                m.SetTextureScale("_MainTex", Vector2.one); m.SetTextureOffset("_MainTex", Vector2.zero);
                EditorUtility.SetDirty(m);
            }

            var root = new GameObject("VFX_LightningStrike");
            var t = root.transform;

            // ---- S0 scorch mark (dark) + ground glow: lowest layers
            var scorch = Flat(t, "S0_Scorch", mScorch, 2.3f, 3.6f, new Color(0.04f, 0.03f, 0.03f, 0.8f), -6);
            AlphaOverLifetime(scorch, 0f, 0f, 0.04f, 1f, 0.7f, 0.9f, 1f, 0f);
            var gg = Flat(t, "S0_GroundGlow", mGlow, 1.0f, 6f, new Color(1f, 0.75f, 0.25f, 1f), -5);
            SizeOverLifetime(gg, 0f, 0.5f, 0.1f, 1f, 1f, 1.1f);
            AlphaOverLifetime(gg, 0f, 0f, 0.02f, 0.9f, 0.5f, 0.5f, 1f, 0f);

            // ---- S2 radial ground cracks (rpg-game: alpha 0 -> 1 at 0.18 -> 1 until 0.71 -> 0, size 0.5 -> 1)
            var crack = Flat(t, "S2_GroundCracks", mCrack, 1.5f, 6.5f, new Color(1f, 0.86f, 0.24f, 1f), -3);
            var cm = crack.main; cm.startRotation = new ParticleSystem.MinMaxCurve(0f, 6.28f);
            SizeOverLifetime(crack, 0f, 0.55f, 0.15f, 0.9f, 1f, 1f);
            AlphaOverLifetime(crack, 0f, 0f, 0.05f, 1f, 0.55f, 1f, 1f, 0f);

            // ---- S1 the strikes: main bolt, then three thinner branch bolts (each hits twice, like line_impact)
            Strike(t, "S1_Bolt_Main", mBolt, Vector3.zero, 0f, 8f, new[] { 0f, 0.1f }, 2);
            Strike(t, "S1_Bolt_Branch1", mBolt, new Vector3(2.2f, 0f, 0.8f), 10f, 4.5f, new[] { 0.14f, 0.24f }, 2);
            Strike(t, "S1_Bolt_Branch2", mBolt, new Vector3(-2.0f, 0f, 1.4f), -12f, 4f, new[] { 0.22f, 0.32f }, 2);

            // ---- S3 white jagged arcs thrown out in every direction (rpg-game: electric_remain)
            Arcs(t, mArcs);

            // ---- S4 impact mix (flash, glow, ring, sparks) at the strike point
            if (mix != null)
            {
                var inst = (GameObject)PrefabUtility.InstantiatePrefab(mix, t);
                inst.name = "S4_ImpactMix";
                inst.transform.localPosition = Vector3.zero;
            }

            var prefab = SavePrefab(root, Root + "/Prefabs/VFX_LightningStrike.prefab");
            var look = new Vector3(0f, 3.2f, 0f);
            const float d = 14f;
            var cam = look + new Vector3(0f, Mathf.Sin(60f * Mathf.Deg2Rad) * d, -Mathf.Cos(60f * Mathf.Deg2Rad) * d);
            Finish(prefab, Root, "LightningStrike", new[] { 0.03f, 0.08f, 0.16f, 0.3f, 0.6f, 1.0f, 1.6f, 2.2f }, cam, look);
        }

        // ---------------------------------------------------------------- ground layers
        static ParticleSystem Flat(Transform parent, string name, Material mat, float life, float size, Color color, int order)
        {
            var ps = Particle(parent, name, mat, lifetime: life, size: size, color: color);
            ps.transform.localPosition = new Vector3(0f, 0.01f * (10 + order), 0f);
            ps.transform.localRotation = Quaternion.Euler(90f, 0f, 0f);
            var r = ps.GetComponent<ParticleSystemRenderer>();
            r.alignment = ParticleSystemRenderSpace.Local;
            r.sortingOrder = order;
            return ps;
        }

        // ---------------------------------------------------------------- one bolt: a Stretched Billboard, the particle moves down a little, so it
        // stretches upwards behind it; the 5-frame sheet breaks the bolt up over the life of the particle (Frame over Time linear)
        static void Strike(Transform parent, string name, Material mat, Vector3 pos, float tilt, float width, float[] times, int stack = 3)
        {
            var ps = Particle(parent, name, mat, lifetime: 0.16f, size: width, color: new Color(1f, 0.92f, 0.55f, 1f));
            ps.transform.localPosition = pos;
            ps.transform.localRotation = Quaternion.Euler(0f, 0f, tilt);
            var main = ps.main;
            main.duration = Life;
            main.startSpeed = 0.1f;
            main.maxParticles = 24;
            var em = ps.emission;
            var bursts = new List<ParticleSystem.Burst>();
            foreach (var tm in times) bursts.Add(new ParticleSystem.Burst(tm, (short)stack));   // stacked copies: additive thin bolt needs the punch
            em.SetBursts(bursts.ToArray());
            var sh = ps.shape;
            sh.enabled = true;
            sh.shapeType = ParticleSystemShapeType.Cone;
            sh.angle = 0f; sh.radius = 0.001f;
            sh.rotation = new Vector3(90f, 0f, 0f);   // the particle moves down: a stretched billboard trails behind it, so the bolt hangs above the point
            var ts = ps.textureSheetAnimation;
            ts.enabled = true;
            ts.mode = ParticleSystemAnimationMode.Grid;
            ts.numTilesX = 5; ts.numTilesY = 1;
            ts.animation = ParticleSystemAnimationType.WholeSheet;
            ts.frameOverTime = LinearFrames();
            var r = ps.GetComponent<ParticleSystemRenderer>();
            r.renderMode = ParticleSystemRenderMode.Stretch;
            r.lengthScale = 8f / width; r.velocityScale = 0f;   // length 8 m
            r.sortingOrder = 8;
        }

        static ParticleSystem.MinMaxCurve LinearFrames()
        {
            var c = new AnimationCurve(new Keyframe(0f, 0f, 1f, 1f), new Keyframe(1f, 1f, 1f, 1f));
            return new ParticleSystem.MinMaxCurve(1f, c);
        }

        // ---------------------------------------------------------------- white arcs (sheet 3 x 3), nearly stationary, stretched along a random direction
        static void Arcs(Transform parent, Material mat)
        {
            var ps = Particle(parent, "S3_Arcs", mat, lifetime: 0.4f, size: 1f, color: new Color(1f, 0.95f, 0.7f, 1f));
            ps.transform.localPosition = new Vector3(0f, 0.2f, 0f);
            var main = ps.main;
            main.duration = Life;
            main.maxParticles = 60;
            main.startLifetime = new ParticleSystem.MinMaxCurve(0.2f, 0.5f);
            main.startSpeed = new ParticleSystem.MinMaxCurve(0.2f, 0.6f);
            main.startSize = new ParticleSystem.MinMaxCurve(1.2f, 2.4f);
            main.startRotation = new ParticleSystem.MinMaxCurve(0f, 6.28f);
            var em = ps.emission;
            em.SetBursts(new[] { new ParticleSystem.Burst(0f, 6), new ParticleSystem.Burst(0.12f, 4) });
            var sh = ps.shape;
            sh.enabled = true;
            sh.shapeType = ParticleSystemShapeType.Cone;
            sh.angle = 70f; sh.radius = 0.3f;
            sh.rotation = new Vector3(-90f, 0f, 0f);
            sh.randomDirectionAmount = 0.5f;
            var ts = ps.textureSheetAnimation;
            ts.enabled = true;
            ts.mode = ParticleSystemAnimationMode.Grid;
            ts.numTilesX = 3; ts.numTilesY = 3;
            ts.animation = ParticleSystemAnimationType.WholeSheet;
            ts.frameOverTime = new ParticleSystem.MinMaxCurve(0f);
            ts.startFrame = new ParticleSystem.MinMaxCurve(0f, 0.99f);
            AlphaOverLifetime(ps, 0f, 0f, 0.15f, 1f, 0.7f, 1f, 1f, 0f);
            var r = ps.GetComponent<ParticleSystemRenderer>();
            r.renderMode = ParticleSystemRenderMode.Stretch;
            r.lengthScale = 1.2f; r.velocityScale = 0.3f;
            r.sortingOrder = 12;
        }
    }
}
#endif
